import { useLayoutEffect, useState, useCallback } from "react";
import { debounce } from "lodash-es";

export const useVisibleChipBar = (
  containerRef: React.RefObject<HTMLElement>,
  allValues: string[],
  moreButtonRef: React.RefObject<HTMLElement>,
) => {
  const [state, setState] = useState<{
    visibleValues: string[];
    overflowValues: string[];
  }>({
    visibleValues: allValues,
    overflowValues: [],
  });

  const measure = useCallback(() => {
    const container = containerRef.current;
    if (!container) return;

    const moreButton = moreButtonRef.current;
    let moreButtonWidth = 0;
    if (moreButton) {
      moreButtonWidth = moreButton.getBoundingClientRect().width;
    }
    const chipElements = Array.from(
      container.querySelectorAll<HTMLElement>(`[data-value]:not([data-value="more"])`),
    );

    const gap = parseFloat(window.getComputedStyle(container).gap) || 0;
    const availableWidth = container.offsetWidth;
    let totalWidth = 0;
    const newVisibleValues: string[] = [];
    const presentValues: string[] = [];

    for (const chipElement of chipElements) {
      const value = chipElement.dataset.value;
      if (value) {
        presentValues.push(value);
        const chipWidth = chipElement.getBoundingClientRect().width;
        if (totalWidth + chipWidth + gap <= availableWidth - moreButtonWidth) {
          totalWidth += chipWidth + gap;
          newVisibleValues.push(value);
        }
      }
    }

    const newOverflowValues = presentValues.filter((val) => !newVisibleValues.includes(val));

    setState((prev) => {
      const visibleChanged =
        prev.visibleValues.length !== newVisibleValues.length ||
        !prev.visibleValues.every((val, index) => val === newVisibleValues[index]);
      const overflowChanged =
        prev.overflowValues.length !== newOverflowValues.length ||
        !prev.overflowValues.every((val, index) => val === newOverflowValues[index]);

      if (!visibleChanged && !overflowChanged) {
        return prev;
      }
      return {
        visibleValues: newVisibleValues,
        overflowValues: newOverflowValues,
      };
    });
  }, [containerRef, moreButtonRef]);

  useLayoutEffect(() => {
    const container = containerRef.current;
    if (!container) return;

    const debouncedMeasure = debounce(measure, 0);
    const observer = new ResizeObserver(debouncedMeasure);
    const mutationObserver = new MutationObserver(debouncedMeasure);

    observer.observe(container);
    mutationObserver.observe(container, { childList: true, subtree: true });

    if (moreButtonRef.current) {
      observer.observe(moreButtonRef.current);
    }

    // Initial measure after first render
    debouncedMeasure();

    return () => {
      observer.disconnect();
      mutationObserver.disconnect();
    };
  }, [measure, containerRef, moreButtonRef, allValues]);

  return state;
};
